			dw kw_absv, var_bul_aim_dx, var_bul_aim_ax
			dw kw_absv, var_bul_aim_dy, var_bul_aim_ay

			; Bul.cls 800: If ax = 0 And ay = 0 Then
			dw kw_cpeqvl, var_bul_aim_ax, 0
			dw kw_ftov, tmp0
			dw kw_cpeqvl, var_bul_aim_ay, 0
