			dw p_bul_aim_r

			; Bul.cls 803: End If
if298_1:

			; Bul.cls 804: If ax <= ay Then
			dw kw_scplevv, var_bul_aim_ax, var_bul_aim_ay
			dw kw_goto_iffalse, if299_1

			; Bul.cls 805: t = atn(ax * 16 \ ay)
