fn_land_upload:		; sub upload (asm keyword), Land.cls line 73
            ld bc, #243B		; Land.cls 74
            ld a, #61		; Land.cls 75
            out (c), a		; Land.cls 76
            inc b		; Land.cls 77
            xor a		; Land.cls 78
            out (c), a		; Land.cls 79
            dec b		; Land.cls 80
            ld a, #62		; Land.cls 81
            out (c), a		; Land.cls 82
            inc b		; Land.cls 83
            xor a		; Land.cls 84
            out (c), a              ; stopped, index 0 [85]
            dec b		; Land.cls 86
            ld a, #60		; Land.cls 87
            out (c), a		; Land.cls 88
            inc b		; Land.cls 89
            ld hl, arr_land_cop		; Land.cls 90
            ld e, 14		; Land.cls 91
fn_land_upload_ln_cop:		; Land.cls 92
            ld a, (hl)		; Land.cls 93
            out (c), a		; Land.cls 94
            inc hl		; Land.cls 95
            dec e		; Land.cls 96
            jr nz, fn_land_upload_ln_cop		; Land.cls 97
            dec b		; Land.cls 98
            ld a, #62		; Land.cls 99
            out (c), a		; Land.cls 100
            inc b		; Land.cls 101
